/**
 * The WebP sibling list, read at build time.
 *
 * The file is generated by `scripts/gen-webp-manifest.mjs` from the
 * images on disk, so this declaration only has to describe its shape.
 *
 * It is imported as the default export because the generated JSON is
 * a plain map: `{"/path/to/photo.png": "/path/to/photo.webp"}`.
 */
declare const WEBP_SIBLINGS: Record<string, string>;
export default WEBP_SIBLINGS;
